        """.trimIndent()

    val schemePalettes: Map<ColorSchemePreset, List<PaletteColor>> by lazy {
        raw.lineSequence()
            .map(String::trim)
            .filter { it.isNotEmpty() }
            .groupBy(
                keySelector = { line -> ColorSchemePreset.valueOf(line.substringBefore("|")) },
                valueTransform = { line ->
                    val parts = line.split("|", limit = 3)
                    val scheme = ColorSchemePreset.valueOf(parts[0])
                    val displayCode = parts[1]
                    val hex = parts[2]
                    PaletteColor(
                        id = "${scheme.name}:${displayCode}",
                        code = displayCode,
                        series = scheme.brandLabel,
                        argb = BeadPalette.hexToArgb(hex),
                    )
                },
            )
    }

    val displayCodeAliasesByScheme: Map<ColorSchemePreset, Map<String, String>> by lazy {
        schemePalettes.mapValues { (_, palette) -> palette.associate { color -> color.code to color.id } }
    }

    val legacyBrandCodeAliasesByScheme: Map<ColorSchemePreset, Map<String, String>> by lazy {
        schemePalettes.mapValues { (scheme, palette) ->
            palette.associate { color -> "${scheme.brandId}:${color.code}" to color.id }
        }
    }
}
